impl FromStr for f64 {
    type Err = ParseFloatError;
    fn from_str(s: &str) -> Result<f64, ParseFloatError> {
        match parse_f64(s) {
            Some(value) => Ok(value),
            None => Err(ParseFloatError { message: String::from("invalid float literal") }),
        }
    }
}

impl Sum<f64> for f64 {
    fn sum<I: Iterator<Item = f64>>(iter: I) -> f64 {
        let mut total: f64 = 0.0;
        for x in iter { total += x; }
        total
    }
}

impl<'a> Sum<&'a f64> for f64 {
    fn sum<I: Iterator<Item = &'a f64>>(iter: I) -> f64 {
        let mut total: f64 = 0.0;
        for x in iter { total += *x; }
        total
    }
}

impl Product<f64> for f64 {
    fn product<I: Iterator<Item = f64>>(iter: I) -> f64 {
        let mut total: f64 = 1.0;
        for x in iter { total *= x; }
        total
    }
}


impl char {
    pub fn is_alphabetic(self) -> bool;
    pub fn is_numeric(self) -> bool;
    pub fn is_alphanumeric(self) -> bool;
    pub fn is_whitespace(self) -> bool;
    pub fn is_uppercase(self) -> bool;
    pub fn is_lowercase(self) -> bool;
    pub fn is_ascii_digit(self) -> bool;
    pub fn is_ascii_punctuation(self) -> bool;
    pub fn to_ascii_uppercase(self) -> char;
    pub fn to_ascii_lowercase(self) -> char;
    pub fn to_digit(self, radix: u32) -> Option<u32>;
    pub fn is_digit(self, radix: u32) -> bool {
        self.to_digit(radix).is_some()
    }
    pub fn len_utf8(self) -> usize;
}

impl FromStr for bool {
    type Err = ParseIntError;
    fn from_str(s: &str) -> Result<bool, ParseIntError> {
        if s == "true" {
            Ok(true)
        } else if s == "false" {
            Ok(false)
        } else {
            Err(ParseIntError { message: String::from("provided string was not `true` or `false`") })
        }
    }
}

pub mod consts {
    pub const PI: f64 = 3.141592653589793;
    pub const E: f64 = 2.718281828459045;
    pub const TAU: f64 = 6.283185307179586;
    pub const SQRT_2: f64 = 1.4142135623730951;
}
